parameters.jsonBody:
={
  "model": $env.OLLAMA_SUMMARY_MODEL || "qwen2.5:7b-instruct-q4_K_M",
  "stream": false,
  "prompt": "You are consolidating personal assistant memory. Reduce duplicates, keep only high-value durable facts, preserve active projects and decisions, and refresh recent context. Return markdown with sections exactly named: IdentityAndPreferences, CurrentProjects, ActiveDecisions, EnvironmentAndTools, RecentContextSummary, ArchiveNotes.\n\nCurrent memory files:\n\n" + ($json.stdout || '')
}

parameters.jsCode:
const response = $json.response || '';
function section(name) {
  const regex = new RegExp(`${name}\\n([\\s\\S]*?)(?=\\n[A-Z][A-Za-z]+(?:And[A-Za-z]+)?\\n|$)`);
  const match = response.match(regex);
  return (match?.[1] || '').trim() || '- No updates generated';
}
const now = new Date().toISOString().replace(/[:.]/g, '-');
return [{ json: {
  identity: `# Identity And Preferences\n\n${section('IdentityAndPreferences')}\n`,
  projects: `# Current Projects\n\n${section('CurrentProjects')}\n`,
  decisions: `# Active Decisions\n\n${section('ActiveDecisions')}\n`,
  tools: `# Environment And Tools\n\n${section('EnvironmentAndTools')}\n`,
  recent: `# Recent Context Summary\n\n${section('RecentContextSummary')}\n`,
  archive: section('ArchiveNotes'),
  now
} }];

parameters.command:
mkdir -p /data/assistant-memory/archive /data/assistant-memory/backups/weekly && cp /data/assistant-memory/memory/*.md /data/assistant-memory/backups/weekly/ 2>/dev/null || true
cat > /data/assistant-memory/memory/identity_and_preferences.md <<'EOF'
{{$json.identity}}
EOF
cat > /data/assistant-memory/memory/current_projects.md <<'EOF'
{{$json.projects}}
EOF
cat > /data/assistant-memory/memory/active_decisions.md <<'EOF'
{{$json.decisions}}
EOF
cat > /data/assistant-memory/memory/environment_and_tools.md <<'EOF'
{{$json.tools}}
EOF
cat > /data/assistant-memory/memory/recent_context_summary.md <<'EOF'
{{$json.recent}}
EOF
cat > /data/assistant-memory/archive/consolidation-{{$json.now}}.md <<'EOF'
# Weekly Consolidation Notes

{{$json.archive}}
EOF

parameters.jsCode:
return [
  { json: { filePath: '/data/assistant-memory/memory/identity_and_preferences.md' } },
  { json: { filePath: '/data/assistant-memory/memory/current_projects.md' } },
  { json: { filePath: '/data/assistant-memory/memory/active_decisions.md' } },
  { json: { filePath: '/data/assistant-memory/memory/environment_and_tools.md' } },
  { json: { filePath: '/data/assistant-memory/memory/recent_context_summary.md' } }
];
